// Fixture behavior plus exact contracts for this workflow's supported text style, not a YAML/security parser.
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { mkdirSync, mkdtempSync, readFileSync, renameSync, rmSync, symlinkSync, unlinkSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import test from 'node:test';
import { fileURLToPath } from 'node:url';
import { check, diskPaths, features, prepare } from './check-workbench-proxies.mjs';

const root = fileURLToPath(new URL('../../', import.meta.url));
const sentinels = ['EventStores/EnsureEventStore.ts', 'DevelopmentTools/ResetKernelState.ts'];
const quiet = () => {};

function proxy(body = 'conflictingEvent?: string;', time = '2026-10-19T10:31:26.8532100Z') {
    return '// Copyright (c) Cratis. All rights reserved.\n\n' +
        '// **DO NOT EDIT** - This file is an automatically generated file.\n' +
        `// @generated by Cratis. Source: Example.Command. Time: ${time}. Hash: ${'A'.repeat(64)}\n` +
        `export interface Command { ${body} }\n`;
}

function put(directory, name, content) {
    const target = path.join(directory, name);
    mkdirSync(path.dirname(target), { recursive: true });
    writeFileSync(target, content);
}

function fixture(context) {
    const scratch = path.join(root, '.ai-work/5046');
    mkdirSync(scratch, { recursive: true });
    const temporary = mkdtempSync(path.join(scratch, 'node-fixture-'));
    context.after(() => rmSync(temporary, { recursive: true }));
    const repository = path.join(temporary, 'repository');
    const source = path.join(repository, features);
    const output = path.join(temporary, 'generated');
    const files = new Map([
        ...sentinels.map(name => [name, proxy()]),
        ['Concurrency/Violation.ts', proxy()], ['Occurrences/Lifecycle.ts', proxy()],
        ['Occurrences/index.ts', "export * from './Lifecycle';\nexport * from './Manual';\n"],
        ['Occurrences/Manual.ts', '// Ordinary comment\nexport const manual = 1;\n'],
        ['Occurrences/Listing.tsx', 'export const Listing = () => <div />;\n']
    ]);
    for (const [name, content] of files) put(source, name, content);
    execFileSync('git', ['init', '--quiet', repository]);
    execFileSync('git', ['-C', repository, 'add', '.']);
    return { repository, source, output, files };
}

function generate(fixture) {
    prepare(fixture.repository, fixture.output, quiet);
    for (const [name, content] of fixture.files) {
        if (content.includes('@generated by Cratis')) put(fixture.output, name, content);
    }
}

function verdict(fixture) {
    const messages = [];
    const code = check(fixture.repository, fixture.output, message => messages.push(message));
    return { code, output: messages.join('\n') };
}

function assertFailure(fixture, diagnostic) {
    const result = verdict(fixture);
    assert.equal(result.code, 1, result.output);
    assert.ok(result.output.includes(diagnostic), result.output);
}

test('equal content passes with only valid timestamp and newline differences', context => {
    const f = fixture(context);
    generate(f);
    for (const name of sentinels) put(f.output, name, proxy(undefined, '2026-11-01T00:00:00Z').replaceAll('\n', '\r\n'));
    const result = verdict(f);
    assert.equal(result.code, 0, result.output);
    for (const text of ['4 tracked proxies', '4 regenerated proxies', '7 compared files']) {
        assert.ok(result.output.includes(text), result.output);
    }
});

test('generic Source metadata retains assembly identity', context => {
    const f = fixture(context);
    generate(f);
    const generic = 'Example.OneOf`1[[Example.Command, Example, Version=1.0.0.0]]';
    for (const directory of [f.source, f.output]) put(directory, sentinels[0], proxy().replace('Example.Command', generic));
    assert.equal(verdict(f).code, 0);
    put(f.output, sentinels[0], proxy().replace('Example.Command', generic.replace('1.0.0.0', '2.0.0.0')));
    assertFailure(f, sentinels[0]);
});

test('prepare copies only handwritten TS/TSX and mixed barrels, with exact bytes', context => {
    const f = fixture(context);
    prepare(f.repository, f.output, quiet);
    assert.deepEqual(diskPaths(f.output).sort(), ['Occurrences/Listing.tsx', 'Occurrences/Manual.ts', 'Occurrences/index.ts']);
    for (const name of diskPaths(f.output)) assert.deepEqual(readFileSync(path.join(f.output, name)), readFileSync(path.join(f.source, name)));
});

for (const [old, replacement] of [['conflictingEvent?: string;', ''], ['Example.Command', 'Other.Command'],
    ['A'.repeat(64), 'B'.repeat(64)], ['Copyright', 'Copywrong']]) {
    test(`actual content comparison rejects ${old} drift even with a retained hash`, context => {
        const f = fixture(context);
        generate(f);
        put(f.output, sentinels[0], proxy().replace(old, replacement));
        assertFailure(f, `${features}/${sentinels[0]}`);
    });
}

test('ordinary handwritten comments are compared', context => {
    const f = fixture(context);
    generate(f);
    put(f.output, 'Occurrences/Manual.ts', f.files.get('Occurrences/Manual.ts').replace('Ordinary', 'Changed'));
    assertFailure(f, 'Occurrences/Manual.ts');
});

test('new untracked generated proxy fails', context => {
    const f = fixture(context);
    generate(f);
    put(f.output, 'New.ts', proxy());
    assertFailure(f, 'not Git-tracked');
});

test('removed proxy fails', context => {
    const f = fixture(context);
    generate(f);
    unlinkSync(path.join(f.output, 'Concurrency/Violation.ts'));
    assertFailure(f, 'missing from regeneration');
});

test('renamed proxy fails as both missing and untracked', context => {
    const f = fixture(context);
    generate(f);
    renameSync(path.join(f.output, 'Concurrency/Violation.ts'), path.join(f.output, 'Concurrency/Renamed.ts'));
    assertFailure(f, 'missing from regeneration');
    assertFailure(f, 'not Git-tracked');
});

for (const barrel of ["export * from './Manual';\n", "export * from './Lifecycle';\nexport * from './Manual';\nexport * from './Removed';\n"]) {
    test(`missing lifecycle or stale removed barrel export fails: ${barrel.trim()}`, context => {
        const f = fixture(context);
        generate(f);
        put(f.output, 'Occurrences/index.ts', barrel);
        assertFailure(f, 'Occurrences/index.ts');
    });
}

test('missing, empty, no-op and non-Debug generation fail', context => {
    const f = fixture(context);
    assert.throws(() => check(f.repository, f.output, quiet));
    mkdirSync(f.output);
    assert.throws(() => check(f.repository, f.output, quiet));
    // Remove only the empty fixture-owned directory, never a real generation tree.
    rmSync(f.output, { recursive: true });
    prepare(f.repository, f.output, quiet);
    assert.throws(() => check(f.repository, f.output, quiet));
    put(f.output, sentinels[0], proxy());
    assert.throws(() => check(f.repository, f.output, quiet), /ResetKernelState/);
});

for (const content of [proxy().replace('Time: 2026', 'Time: invalid2026'), proxy().replace('. Hash:', '. Broken:'),
    'export const first = 1;\n' + proxy(), proxy(undefined, '2026-02-30T00:00:00Z')]) {
    test(`malformed or misplaced metadata fails: ${content.slice(-80)}`, context => {
        const f = fixture(context);
        put(f.source, sentinels[0], content);
        assert.throws(() => prepare(f.repository, f.output, quiet));
    });
}

test('unsafe destination, existing destination, and symlinked input fail', context => {
    const f = fixture(context);
    for (const target of [f.source, path.join(f.source, 'nested'), path.dirname(f.source)]) {
        assert.throws(() => prepare(f.repository, target, quiet), /overlaps/);
    }
    mkdirSync(f.output);
    assert.throws(() => prepare(f.repository, f.output, quiet), /already exists/);
    unlinkSync(path.join(f.source, sentinels[0]));
    symlinkSync(path.join(f.source, sentinels[1]), path.join(f.source, sentinels[0]));
    assert.throws(() => prepare(f.repository, path.join(f.output, 'fresh'), quiet), /Symlink/);
});

test('empty tracked input, missing input and untracked generated input fail', context => {
    const f = fixture(context);
    execFileSync('git', ['-C', f.repository, 'rm', '-r', '--cached', '--quiet', '.']);
    assert.throws(() => prepare(f.repository, f.output, quiet), /No tracked/);
    execFileSync('git', ['-C', f.repository, 'add', '.']);
    unlinkSync(path.join(f.source, sentinels[0]));
    assert.throws(() => prepare(f.repository, f.output, quiet));
    put(f.source, sentinels[0], proxy());
    put(f.source, 'Untracked.ts', proxy());
    assert.throws(() => prepare(f.repository, f.output, quiet), /Untracked.ts/);
});

test('output outside tracked Features is irrelevant', context => {
    const f = fixture(context);
    generate(f);
    put(f.repository, 'unrelated.ts', proxy());
    assert.equal(verdict(f).code, 0);
});

function workflowSteps(text) {
    const [, job] = text.split('\n  dotnet-build:\n');
    assert.ok(job, 'exact dotnet-build job style required; actionlint validates YAML');
    assert.ok(job.startsWith("    needs: [already-ran, wire-compatibility, grain-compatibility]\n    if: needs.already-ran.outputs.skip != 'true'\n    runs-on: ubuntu-latest\n"));
    return job.split('\n      - name: ').slice(1).map(block => block.trimEnd());
}

function exactStep(steps, name, body) {
    const matches = steps.filter(step => step.split('\n')[0] === name);
    assert.equal(matches.length, 1, name);
    assert.equal(matches[0], `${name}\n${body}`, 'exact supported step style, no condition or continue-on-error');
    return steps.indexOf(matches[0]);
}

test('ordinary PR exact steps run Node fixtures, isolated Debug generation and comparison before Release', () => {
    const text = readFileSync(path.join(root, '.github/workflows/dotnet-build.yml'), 'utf8');
    const steps = workflowSteps(text);
    const selected = [
        exactStep(steps, 'Spec Workbench proxy freshness guard', '        run: node .github/scripts/test-check-workbench-proxies.mjs'),
        exactStep(steps, 'Set isolated Workbench proxy destination', '        run: echo "WORKBENCH_PROXIES=$RUNNER_TEMP/workbench-proxies" >> "$GITHUB_ENV"'),
        exactStep(steps, 'Prepare isolated Workbench proxy generation', '        run: node .github/scripts/check-workbench-proxies.mjs prepare --output "$WORKBENCH_PROXIES"'),
        exactStep(steps, 'Generate native Debug Workbench proxies', '        run: >-\n' +
            '          dotnet build Source/Kernel/Core/Core.csproj --configuration Debug\n' +
            '          -p:DisableProxyGenerator=false -p:DisableGrpcContractGeneration=true\n' +
            '          -p:DisableProtoGeneration=true -p:DisableDockerBuild=true\n' +
            '          -p:CratisProxiesIncremental=false "-p:CratisProxiesOutputPath=$WORKBENCH_PROXIES"'),
        exactStep(steps, 'Check Workbench proxy freshness', '        run: node .github/scripts/check-workbench-proxies.mjs check --generated "$WORKBENCH_PROXIES"'),
        exactStep(steps, 'Build', '        run: dotnet build --configuration Release -p:DisableProxyGenerator=true -p:DisableDockerBuild=true -p:ForceCodeGeneration=true')
    ];
    assert.deepEqual(selected, [...selected].sort((a, b) => a - b));
});

test('native existing path assertion and its specs remain CI-owned and precede fixtures', () => {
    const steps = workflowSteps(readFileSync(path.join(root, '.github/workflows/dotnet-build.yml'), 'utf8'));
    const assertion = steps.findIndex(step => step.startsWith('Assert the build-affecting path contract\n'));
    assert.ok(assertion >= 0);
    assert.ok(steps[assertion].includes('          python3 .github/scripts/assert-build-affecting-paths.py\n'));
    assert.ok(steps[assertion].includes('          python3 -B .github/scripts/test-assert-build-affecting-paths.py'));
    assert.ok(assertion < steps.findIndex(step => step.startsWith('Spec Workbench proxy freshness guard\n')));
});
